import{_ as p,a0 as t,w as c,s as o,ao as d,I as l,x as s,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 ACL 设置用户访问指定文件/目录的权限 | LCTT x X-CMD","titleTemplate":false,"description":"使用 ACL 设置用户访问指定文件/目录的权限 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 ACL 设置用户访问指定文件/目录的权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 ACL 设置用户访问指定文件/目录的权限 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL","title":"使用 ACL 设置用户访问指定文件/目录的权限","tag":"201801","desc":""},"relativePath":"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL.md","filePath":"[post].md"}'),r={name:"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL.md"};function h(g,a,k,b,u,f){const e=t("Link");return c(),o("div",null,[a[13]||(a[13]=d(`<h1 id="使用-acl-设置用户访问指定文件-目录的权限" tabindex="-1">使用 ACL 设置用户访问指定文件/目录的权限 <a class="header-anchor" href="#使用-acl-设置用户访问指定文件-目录的权限" aria-label="Permalink to “使用 ACL 设置用户访问指定文件/目录的权限”">​</a></h1><p>当提到文件和目录的权限时，你的第一反应可能是“属主/群组/其它”权限。 这些权限可以通过 <code>chmod</code>、 <code>chown</code> 等命令来修改。</p><p>文件和目录都有属主 (文件所有者 )、群组 (所属组) 以及其它权限，这些权限构成一个集合。 然而这些权限集合有它的局限性，无法做到为不同的用户设置不同的权限。</p><p>Linux 对文件和目录有以下默认权限。</p><ul><li>文件 -&gt; <code>644</code> -&gt; <code>-rw-r-r-</code> （所有者有读写权限，组成员有只读权限， 其他人也只有读权限）</li><li>目录 -&gt; <code>755</code> -&gt; <code>drwxr-xr-x</code> （所有者有读、写和执行权限，组成员有读和执行的权限，其他人也有读和执行的权限）</li></ul><p>比如： 默认情况下，所有者可以访问和编辑他们自己主目录中的文件， 也可以访问相关同组人的文件，但他们不能修改这些文件，因为组成员没有写权限，而且让组成员有写权限也是不明智的。 基于同样的原因，他/她也不能修改其他人的文件。 然而在某些情况下，多个用户想要修改同一个文件， 那该怎么办呢？</p><p>假设有个名叫 <code>magi</code> 的用户，他想要修改 <code>httpd.conf</code> 文件怎么办呢？ 这个文件是归 root 用户所有的，这样如何授权呢？ 为了解决这种情况，<ruby>访问控制列表<rt>Access Control List</rt></ruby>（ACL）诞生了。</p><h3 id="什么是-acl" tabindex="-1">什么是 ACL？ <a class="header-anchor" href="#什么是-acl" aria-label="Permalink to “什么是 ACL？”">​</a></h3><p>ACL 表示<ruby>访问控制列表<rt>Access Control List</rt></ruby>（ACL），它为文件系统提供了附加的、更具有弹性的权限机制。 它被设计来为补充 UNIX 文件权限机制。 ACL 允许你赋予任何某用户/组访问某项资源的权限。 <code>setfacl</code> 与 <code>getfacl</code> 命令会帮助你管理 ACL 而不会有任何麻烦。</p><h3 id="什么是-setfacl" tabindex="-1">什么是 setfacl？ <a class="header-anchor" href="#什么是-setfacl" aria-label="Permalink to “什么是 setfacl？”">​</a></h3><p><code>setfacl</code> 用于设置文件和目录的 ACL。</p><h3 id="什么-getfacl" tabindex="-1">什么 getfacl？ <a class="header-anchor" href="#什么-getfacl" aria-label="Permalink to “什么 getfacl？”">​</a></h3><p><code>getfacl</code> - 获取文件的 ACL 。对于每个文件， <code>getfacl</code> 都会显示文件名、文件所有者、所属组以及ACL。 如果目录有默认 ACL， <code>getfacl</code> 也会显示这个默认的 ACL。</p><h3 id="如何确认是否启用了-acl" tabindex="-1">如何确认是否启用了 ACL？ <a class="header-anchor" href="#如何确认是否启用了-acl" aria-label="Permalink to “如何确认是否启用了 ACL？”">​</a></h3><p>运行 <code>tune2fs</code> 命令来检查是否启用了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -l /dev/sdb1 | grep options</span></span>
<span class="line"><span>Default mount options: (none)</span></span></code></pre></div><p>上面的输出很明显第说明 <code>/dev/sdb1</code> 分区没有启用 ACL。</p><p>如果结果中没有列出 <code>acl</code>，则你需要在挂载选项中加上 <code>acl</code>。 为了让它永久生效， 修改 <code>/etc/fstab</code> 中 <code>/app</code> 这一行成这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># more /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UUID=f304277d-1063-40a2-b9dc-8bcf30466a03 / ext4 defaults 1 1</span></span>
<span class="line"><span>/dev/sdb1 		 /app ext4 defaults，acl 1 1</span></span></code></pre></div><p>或者，你也可以使用下面命令将其添加道文件系统的超级块中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -o +acl /dev/sdb1</span></span></code></pre></div><p>现在，通过运行以下命令来动态修改选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,acl /app</span></span></code></pre></div><p>再次运行 <code>tune2fs</code> 命令来看选项中是否有 <code>acl</code> 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -l /dev/sdb1 | grep options</span></span>
<span class="line"><span>Default mount options： acl</span></span></code></pre></div><p>嗯，现在 <code>/dev/sdb1</code> 分区中有 ACL 选项了。</p><h3 id="如何查看默认的-acl-值" tabindex="-1">如何查看默认的 ACL 值 <a class="header-anchor" href="#如何查看默认的-acl-值" aria-label="Permalink to “如何查看默认的 ACL 值”">​</a></h3><p>要查看文件和目录默认的 ACL 值，可以使用 <code>getfacl</code> 命令后面加上文件路径或者目录路径。 注意， 当你对非 ACL 文件/目录运行 <code>getfacl</code> 命令时， 则不会显示附加的 <code>user</code> 和 <code>mask</code> 参数值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><h3 id="如何为文件设置-acl" tabindex="-1">如何为文件设置 ACL <a class="header-anchor" href="#如何为文件设置-acl" aria-label="Permalink to “如何为文件设置 ACL”">​</a></h3><p>以下面格式运行 <code>setfacl</code> 命令可以为指定文件设置 ACL。在下面的例子中，我们会给 <code>magi</code> 用户对 <code>/etc/apache2/apache2.conf</code> 文件 <code>rwx</code> 的权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m u:magi:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>仔细分析起来：</strong></p><ul><li><code>setfacl</code>： 命令</li><li><code>-m</code>： 修改文件的当前 ACL</li><li><code>u</code>： 指明用户</li><li><code>magi</code>： 用户名</li><li><code>rwx</code>： 要设置的权限</li><li><code>/etc/apache2/apache2.conf</code>： 文件名称</li></ul><p>再查看一次新的 ACL 值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>user:magi:rwx</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>mask::rwx</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><p>注意： 若你发现文件或目录权限后面有一个加号（<code>+</code>），就表示设置了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -lh /etc/apache2/apache2.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 7.1K Sep 19 14:58 /etc/apache2/apache2.conf</span></span></code></pre></div><h3 id="如何为目录设置-acl" tabindex="-1">如何为目录设置 ACL <a class="header-anchor" href="#如何为目录设置-acl" aria-label="Permalink to “如何为目录设置 ACL”">​</a></h3><p>以下面格式运行 <code>setfacl</code> 命令可以递归地为指定目录设置 ACL。在下面的例子中，我们会将 <code>/etc/apache2/sites-available/</code> 目录中的 <code>rwx</code> 权限赋予 <code>magi</code> 用户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -Rm u:magi:rwx /etc/apache2/sites-available/</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-R</code>： 递归到子目录中</li></ul><p>再次查看一下新的 ACL 值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/sites-available/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/sites-available/</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rwx</span></span>
<span class="line"><span>user:magi:rwx</span></span>
<span class="line"><span>group::r-x</span></span>
<span class="line"><span>mask::rwx</span></span>
<span class="line"><span>other::r-x</span></span></code></pre></div><p>现在 <code>/etc/apache2/sites-available/</code> 中的文件和目录都设置了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -lh /etc/apache2/sites-available/</span></span>
<span class="line"><span>total 20K</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Sep 19 14:56 000-default.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 6.2K Sep 19 14:56 default-ssl.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Dec 8 02:57 mywebpage.com.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Dec 7 19:07 testpage.com.conf</span></span></code></pre></div><h3 id="如何为组设置-acl" tabindex="-1">如何为组设置 ACL <a class="header-anchor" href="#如何为组设置-acl" aria-label="Permalink to “如何为组设置 ACL”">​</a></h3><p>以下面格式为指定文件运行 <code>setfacl</code> 命令。在下面的例子中，我们会给 <code>appdev</code> 组赋予 <code>/etc/apache2/apache2.conf</code> 文件的 <code>rwx</code> 权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m g:appdev:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>g</code>： 指明一个组</li></ul><p>对多个用户和组授权，只需要用 <code>逗号</code> 区分开，就像下面这样。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m u:magi:rwx,g:appdev:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><h3 id="如何删除-acl" tabindex="-1">如何删除 ACL <a class="header-anchor" href="#如何删除-acl" aria-label="Permalink to “如何删除 ACL”">​</a></h3><p>以下面格式运行 <code>setfacl</code> 命令会删除文件对指定用户的 ACL。这只会删除用户权限而保留 <code>mask</code> 的值为只读。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -x u:magi /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-x</code>： 从文件的 ACL 中删除</li></ul><p>再次查看 ACL 值。在下面的输出中我们可以看到 <code>mask</code> 的值是读。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>mask::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><p>使用 <code>-b</code> 来删除文件中所有的 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -b /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-b</code>： 删除所有的 ACL 条目</li></ul><p>再次查看删掉后的 ACl 值就会发现所有的东西都不见了，包括 <code>mask</code> 的值也不见了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><h3 id="如何备份并还原-acl" tabindex="-1">如何备份并还原 ACL <a class="header-anchor" href="#如何备份并还原-acl" aria-label="Permalink to “如何备份并还原 ACL”">​</a></h3><p>下面命令可以备份和还原 ACL 的值。要制作备份， 需要进入对应的目录然后这样做（假设我们要备份 <code>sites-available</code> 目录中的 ACL 值)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /etc/apache2/sites-available/</span></span>
<span class="line"><span># getfacl -R * &gt; acl_backup_for_folder</span></span></code></pre></div><p>还原的话，则运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl --restore=/etc/apache2/sites-available/acl_backup_for_folder</span></span></code></pre></div><hr>`,73)),l("p",null,[a[1]||(a[1]=s("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-configure-access-control-lists-acls-setfacl-getfacl-linux/"},{default:i(()=>[...a[0]||(a[0]=[s("https://www.2daygeek.com/how-to-configure-access-control-lists-acls-setfacl-getfacl-linux/",-1)])]),_:1})]),l("p",null,[a[5]||(a[5]=s("作者：",-1)),n(e,{href:"https://www.2daygeek.com"},{default:i(()=>[...a[2]||(a[2]=[s("MAGESH MARUTHAMUTHU",-1)])]),_:1}),a[6]||(a[6]=s(" 译者：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[7]||(a[7]=s(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[10]||(a[10]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[s("Linux中国",-1)])]),_:1}),a[12]||(a[12]=s(" 荣誉推出",-1))])])}const A=p(r,[["render",h]]);export{x as __pageData,A as default};
